import React, { useState, useEffect, useRef } from 'react';
import { Card, Table, Form, Row, Col, Spinner, Button } from 'react-bootstrap';
import * as XLSX from 'xlsx';
import moment from 'moment';
import { usePageTitle, useRedux } from '../../../hooks';
import {
    getBranchRequest, getDepartmentRequest, getStaffAttendanceListRequest, resetGetEmpAttendanceList
    , resetGetBranch, resetGetDepartment
} from '../../../redux/actions';
import { NotificationContainer } from 'react-notifications';
import { FaCheckCircle, FaTimesCircle, FaAdjust, FaUmbrellaBeach, FaSun, FaMinus } from 'react-icons/fa';
import _ from 'lodash';
import { findArrObj } from '../../../utils/AllFunction';
import noProfile from '../../../assets/images/noprofile_images.jpg';
import { baseURL } from '../../../api/ApiConfig';

const Index = () => {

    usePageTitle({
        title: 'Report',
        breadCrumbItems: [
            {
                path: '/report/staff-attendance-report',
                label: 'Report',
            },
            {
                path: '/report/staff-attendance-report',
                label: 'Staff Attendance Report',
                active: true,
            },
        ],
    });

    const { dispatch, appSelector } = useRedux();
    const loginInfo = localStorage.getItem('loginInfo');
    const localData = JSON.parse(loginInfo);
    const pageAccessData = findArrObj(localData[0].pagePermission, 'label', "Staff Attendance List");
    const accessIds = (pageAccessData[0]?.access || '').split(',').map(id => id.trim());
    const branchIdforRole = localData[0].branchId;
    const roleIdforRole = localData[0].roleId;
    const employeeIdforRole = localData[0]?.employeeId || null;
    const tableRef = useRef(null);

    const [state, setState] = useState({
        month: moment().format('YYYY-MM'),
        branchId: branchIdforRole,
        departmentId: null
    });

    const [optionListState, setOptionListState] = useState({
        departmentList: [
            {
                "departmentId": null,
                "departmentName": "All",
            },
        ],
        branchList: [{
            "branchId": null,
            "branchName": "All",
        }]
    });

    const [isLoading, setIsLoading] = useState(false);
    const [attendanceData, setAttendanceData] = useState({
        attendanceDetail: [],
        monthCount: {},
        perDayAbsent: {},
        perDayPresent: {}
    });

    const {
        getStaffAttendanceListSuccess,
        getStaffAttendanceListout,
        getStaffAttendanceListFailure,
        getBranchSuccess,
        getBranchList,
        getBranchFailure,
        getDepartmentSuccess,
        getDepartmentList,
        getDepartmentFailure
    } = appSelector((state) => ({
        getStaffAttendanceListSuccess: state.staffAttendanceReducer.getStaffAttendanceListSuccess,
        getStaffAttendanceListout: state.staffAttendanceReducer.getStaffAttendanceListout || {},
        getStaffAttendanceListFailure: state.staffAttendanceReducer.getStaffAttendanceListFailure,
        getBranchSuccess: state.branchReducer.getBranchSuccess,
        getBranchList: state.branchReducer.getBranchList,
        getBranchFailure: state.branchReducer.getBranchFailure,
        getDepartmentSuccess: state.departmentReducer.getDepartmentSuccess,
        getDepartmentList: state.departmentReducer.getDepartmentList,
        getDepartmentFailure: state.departmentReducer.getDepartmentFailure,
    }));

    useEffect(() => {
        dispatch(getBranchRequest());
        dispatch(getDepartmentRequest());
    }, []);

    useEffect(() => {
        setIsLoading(true);
        const req = {
            attendanceDate: moment(state.month).format('YYYY-MM-DD'),
            branchId: state.branchId === null ? null : state.branchId,
            departmentId: state.departmentId === null ? null : state.departmentId
        };
        dispatch(getStaffAttendanceListRequest(req));
    }, [state.month, state.branchId, state.departmentId]);

    useEffect(() => {
        if (getStaffAttendanceListSuccess) {
            setIsLoading(false);
            setAttendanceData(getStaffAttendanceListout);
            dispatch(resetGetEmpAttendanceList());
        } else if (getStaffAttendanceListFailure) {
            setIsLoading(false);
            dispatch(resetGetEmpAttendanceList());
        }
    }, [getStaffAttendanceListSuccess, getStaffAttendanceListFailure]);

    useEffect(() => {
        if (getBranchSuccess) {
            setIsLoading(false);
            setOptionListState(prev => ({
                ...prev,
                branchList: roleIdforRole === 1
                    ? [...prev.branchList, ...getBranchList]
                    : getBranchList.filter(b => b.branchId === branchIdforRole)
            }));
            dispatch(resetGetBranch());
        } else if (getBranchFailure) {
            setIsLoading(false);
            dispatch(resetGetBranch());
        }
    }, [getBranchSuccess, getBranchFailure]);

    useEffect(() => {
        if (getDepartmentSuccess) {
            setIsLoading(false);
            setOptionListState(prev => ({
                ...prev,
                departmentList: [...prev.departmentList, ...getDepartmentList]
            }));
            dispatch(resetGetDepartment());
        } else if (getDepartmentFailure) {
            setIsLoading(false);
            dispatch(resetGetDepartment());
        }
    }, [getDepartmentSuccess, getDepartmentFailure]);

    const renderIcon = (status) => {
        switch (status) {
            case "present": return <FaCheckCircle color=" #28a745" size={18} />;
            case "absent": return <FaTimesCircle color="#FF0000" size={18} />;
            case "halfday": return <FaAdjust color="DodgerBlue" size={18} />;
            case "holiday": return <FaUmbrellaBeach color="gray" size={18} />;
            case "sunday": return <FaSun color="orange" size={18} />;
            default: return "-";
        }
    };


    const exportToExcel = () => {
        const wb = XLSX.utils.book_new();
        const monthLabel = moment(state.month).format('MMMM YYYY');
        const titleRow = [`Staff Attendance Report for ${monthLabel}`];
        const emptyRow = [];
        const dayTotals = Array.from({ length: 31 }, (_, i) => {
            const day = String(i + 1).padStart(2, '0');
            const dateKey = `${moment(state.month).format('YYYY-MM')}-${day}`;
            let presentCount = 0;
            let halfDayCount = 0;
            let absentCount = 0;

            attendanceData?.attendanceDetail?.forEach((emp) => {
                const status = emp.dailyStatus?.[dateKey];
                if (status === "present") presentCount++;
                else if (status === "halfday") halfDayCount++;
                else if (status === "absent") absentCount++;
            });

            return { presentCount, halfDayCount, absentCount };
        });

        const headers = [
            ['No', 'Employee Name', 'Summary', '', '', ...Array.from({ length: 31 }, (_, i) => (i + 1))],
            ['', '', 'Present', 'Half Day', 'Absent', ...Array(31).fill('')],
            ['', 'Present (P)', '', '', '', ...dayTotals.map(day => day.presentCount)],
            ['', 'Half Day (H)', '', '', '', ...dayTotals.map(day => day.halfDayCount)],
            ['', 'Absent (A)', '', '', '', ...dayTotals.map(day => day.absentCount)]
        ];

        const dataRows = attendanceData?.attendanceDetail?.map((employee, index) => [
            index + 1,
            employee.staffName,
            employee?.presentCount || 0,
            employee?.halfDayCount || 0,
            employee?.absentCount || 0,
            ...Array.from({ length: 31 }, (_, i) => {
                const day = String(i + 1).padStart(2, '0');
                const dateKey = `${moment(state.month).format('YYYY-MM')}-${day}`;
                const status = employee?.dailyStatus[dateKey] || "";
                switch (status) {
                    case "present": return "P";
                    case "absent": return "A";
                    case "halfday": return "H";
                    case "holiday": return "HD";
                    case "sunday": return "S";
                    default: return "X";
                }
            })
        ]);

        const finalData = [
            titleRow,
            emptyRow,
            ...headers,
            ...(dataRows || [])
        ];

        const ws = XLSX.utils.aoa_to_sheet(finalData);

        ws['!cols'] = [
            { wch: 5 },
            { wch: 25 },
            { wch: 8 },
            { wch: 8 },
            { wch: 8 },
            ...Array(31).fill({ wch: 5 })
        ];

        ws['!merges'] = [
            { s: { r: 0, c: 0 }, e: { r: 0, c: 35 } },
            { s: { r: 2, c: 2 }, e: { r: 2, c: 4 } }
        ];

        XLSX.utils.book_append_sheet(wb, ws, "Attendance");

        const legendData = [
            ["LEGEND"],
            ["Code", "Description"],
            ["P", "Present"],
            ["H", "Half Day"],
            ["A", "Absent"],
            ["HD", "Holiday"],
            ["S", "Sunday"]
            ["X", "Not Attendance Marked"]
        ];

        const noteWs = XLSX.utils.aoa_to_sheet(legendData);
        noteWs['!cols'] = [{ wch: 10 }, { wch: 20 }];
        XLSX.utils.book_append_sheet(wb, noteWs, "Legend")

        const fileName = `Staff_Attendance_${moment(state.month).format('YYYY_MM')}.xlsx`;
        XLSX.writeFile(wb, fileName);
    };
    const onMonthChange = (e) => {
        setState(prev => ({ ...prev, month: e.target.value }));
    };

    const onBranchFilter = (option, formName, uniqueKey, displayKey) => {
        setState(prev => ({
            ...prev,
            [formName]: option[uniqueKey] === null ? null : option[uniqueKey],
            departmentId: null
        }));
    };

    const onDepartmentFilter = (option, formName, uniqueKey, displayKey) => {
        setState(prev => ({
            ...prev,
            [formName]: option[uniqueKey] === null ? null : option[uniqueKey]
        }));
    };

    return (
        <React.Fragment>
            <NotificationContainer />
            {isLoading ? (
                <div className="bg-light opacity-0.25">
                    <div className="d-flex justify-content-center m-5">
                        <Spinner className="mt-5 mb-5" animation="border" />
                    </div>
                </div>
            ) : (
                <Row>
                    <Col>
                        <Card>
                            <Card.Body>
                                <Row>
                                    <Col sm={6}>
                                        <h4>Staff Attendance Report</h4>
                                    </Col>
                                </Row>
                                {(_.includes(accessIds, '1')) && (
                                    <div className="border">
                                        <Card>
                                            <Card.Body>
                                                <Row className="d-flex">
                                                    <Col sm={2}>
                                                        <Form.Group controlId="monthFilter">
                                                            <Form.Control
                                                                type="month"
                                                                value={state.month}
                                                                onChange={onMonthChange}
                                                            />
                                                        </Form.Group>
                                                    </Col>
                                                    {roleIdforRole === 1 && (
                                                        <Col sm={2}>
                                                            <Form.Select
                                                                value={state.branchId === null ? null : state.branchId}
                                                                onChange={(e) => onBranchFilter(
                                                                    { branchId: e.target.value === "null" ? null : parseInt(e.target.value) },
                                                                    'branchId',
                                                                    'branchId',
                                                                    'branchName'
                                                                )}
                                                            >
                                                                {optionListState.branchList.map((branch) => (
                                                                    <option key={branch.branchId} value={branch.branchId === null ? "null" : branch.branchId}>
                                                                        {branch.branchName}
                                                                    </option>
                                                                ))}
                                                            </Form.Select>
                                                        </Col>
                                                    )}
                                                    <Col sm={2}>
                                                        <Form.Group controlId="departmentFilter">
                                                            <Form.Select
                                                                value={state.departmentId === null ? null : state.departmentId}
                                                                onChange={(e) => onDepartmentFilter(
                                                                    { departmentId: e.target.value === "null" ? null : parseInt(e.target.value) },
                                                                    'departmentId',
                                                                    'departmentId',
                                                                    'departmentName'
                                                                )}
                                                            >
                                                                {optionListState.departmentList.map((dept) => (
                                                                    <option key={dept.departmentId} value={dept.departmentId === null ? "null" : dept.departmentId}>
                                                                        {dept.departmentName}
                                                                    </option>
                                                                ))}
                                                            </Form.Select>
                                                        </Form.Group>
                                                    </Col>
                                                    <Col sm={2}>
                                                        <Button variant="success" onClick={exportToExcel}>
                                                            Export to Excel
                                                        </Button>
                                                    </Col>
                                                </Row>
                                            </Card.Body>


                                            <Card.Body style={{ padding: 0 }}>
                                                <style>
                                                    {`
          .attendance-table th,
          .attendance-table td {
            height: 68px;
            vertical-align: middle;
            text-align: center;
            padding: 4px;
            white-space: nowrap;
          }

          .sticky-col {
            position: sticky;
            left: 0;
            z-index: 2;
            background: white;
          }

          .attendance-fixed {
            min-width: 350px;
          }

          .attendance-scroll {
            overflow-x: auto;
          }

          .header-cell {
            background: #f9f9f9;
          }
        `}
                                                </style>

                                                <div style={{ display: 'flex', width: '100%' }}>
                                                    <div className="attendance-fixed">
                                                        <Table bordered className="attendance-table mb-0">
                                                            <thead>
                                                                <tr>
                                                                    <td colSpan={5} className="header-cell">
                                                                        <div className="d-flex align-items-end flex-column px-2">
                                                                            <div className="text-success fw-bold">P</div>
                                                                            <div className="text-primary fw-bold">H</div>
                                                                            <div className="text-danger fw-bold">A</div>
                                                                        </div>
                                                                    </td>
                                                                </tr>
                                                                <tr>
                                                                    <th>No</th>
                                                                    <th>Name</th>
                                                                    <th className="text-success p-2">P</th>
                                                                    <th className="text-primary p-2">H</th>
                                                                    <th className="text-danger p-2">A</th>
                                                                </tr>
                                                            </thead>
                                                            <tbody>
                                                                {attendanceData?.attendanceDetail?.map((employee, index) => (
                                                                    <tr key={index}>
                                                                        <td>{index + 1}</td>
                                                                        <td>
                                                                            <div style={{ display: 'flex', alignItems: 'center' }}>
                                                                                <img
                                                                                    src={employee?.staffProfile ? `${baseURL}${employee.staffProfile}` : noProfile}
                                                                                    alt="staffProfile"
                                                                                    className="rounded-circle"
                                                                                    crossOrigin="anonymous"
                                                                                    onError={(e) => {
                                                                                        e.target.onerror = null;
                                                                                        e.target.src = noProfile;
                                                                                    }}
                                                                                    style={{ width: "45px", height: "45px", objectFit: "cover", marginRight: "10px" }}
                                                                                />
                                                                                <div>
                                                                                    <div style={{ fontSize: '15px', fontWeight: '600' }}>{employee?.staffName}</div>
                                                                                    <div style={{ fontSize: '12px', color: '#888' }}>{employee?.staffCode}</div>
                                                                                </div>
                                                                            </div>
                                                                        </td>
                                                                        <td className="text-success fw-bold">{employee?.presentCount || 0}</td>
                                                                        <td className="text-primary fw-bold">{employee?.halfDayCount || 0}</td>
                                                                        <td className="text-danger fw-bold">{employee?.absentCount || 0}</td>
                                                                    </tr>
                                                                ))}
                                                            </tbody>
                                                        </Table>
                                                    </div>

                                                    {/* Scrollable Columns */}
                                                    <div className="attendance-scroll" style={{ flex: 1 }}>
                                                        <Table bordered className="attendance-table mb-0">
                                                            <thead>
                                                                <tr>
                                                                    {[...Array(31)].map((_, i) => {
                                                                        const day = String(i + 1).padStart(2, '0');
                                                                        const dateKey = `${moment(state.month).format('YYYY-MM')}-${day}`;
                                                                        let presentCount = 0, halfDayCount = 0, absentCount = 0;

                                                                        attendanceData?.attendanceDetail?.forEach((emp) => {
                                                                            const status = emp.dailyStatus?.[dateKey];
                                                                            if (status === "present") presentCount++;
                                                                            else if (status === "halfday") halfDayCount++;
                                                                            else if (status === "absent") absentCount++;
                                                                        });

                                                                        return (
                                                                            <th key={i} style={{ minWidth: 40 }}>
                                                                                <div className="text-success">{presentCount}</div>
                                                                                <div className="text-primary">{halfDayCount}</div>
                                                                                <div className="text-danger">{absentCount}</div>
                                                                            </th>
                                                                        );
                                                                    })}
                                                                </tr>
                                                                <tr>
                                                                    {[...Array(31)].map((_, i) => (
                                                                        <th key={i} style={{ minWidth: 40 }}>{i + 1}</th>
                                                                    ))}
                                                                </tr>
                                                            </thead>
                                                            <tbody>
                                                                {attendanceData?.attendanceDetail?.map((employee, index) => (
                                                                    <tr key={index}>
                                                                        {[...Array(31)].map((_, i) => {
                                                                            const day = String(i + 1).padStart(2, '0');
                                                                            const dateKey = `${moment(state.month).format('YYYY-MM')}-${day}`;
                                                                            const status = employee?.dailyStatus?.[dateKey] || "";
                                                                            return (
                                                                                <td key={i} style={{ minWidth: 40 }}>{renderIcon(status)}</td>
                                                                            );
                                                                        })}
                                                                    </tr>
                                                                ))}
                                                            </tbody>
                                                        </Table>
                                                    </div>
                                                </div>
                                            </Card.Body>
                                        </Card>
                                    </div>
                                )}
                            </Card.Body>
                        </Card>


                    </Col >
                    <Card>
                        <Card.Body>

                            <h4 style={{ marginBottom: '20px', fontWeight: 'bold' }}>Attendance Legend</h4>
                            <ul style={{ listStyleType: 'none', padding: 0, lineHeight: '2.2' }}>
                                <li>
                                    <FaCheckCircle color="#28a745" size={18} />{' '}
                                    <strong style={{ fontSize: '18px', color: '#28a745' }}>Present</strong>
                                </li>
                                <li>
                                    <FaTimesCircle color="#dc3545" size={18} />{' '}
                                    <strong style={{ fontSize: '18px', color: '#dc3545' }}>Absent</strong>
                                </li>
                                <li>
                                    <FaAdjust color="#007bff" size={18} />{' '}
                                    <strong style={{ fontSize: '18px', color: '#007bff' }}>Half Day</strong>
                                </li>
                                <li>
                                    <FaUmbrellaBeach color="#9400ff" size={18} />{' '}
                                    <strong style={{ fontSize: '18px', color: '#9400ff' }}>Holiday</strong>
                                </li>
                                <li>
                                    <FaSun color="#fd7e14" size={18} />{' '}
                                    <strong style={{ fontSize: '18px', color: '#fd7e14' }}>Sunday</strong>
                                </li>
                                <li>
                                    <FaMinus color="#6c757d" size={18} />{' '}
                                    <strong style={{ fontSize: '18px', color: '#6c757d' }}>Not Marked Attendance</strong>
                                </li>
                            </ul>
                        </Card.Body>
                    </Card>
                </Row >
            )}
        </React.Fragment >
    );
};

export default Index;